link=lambda key: key+'.html?preview=1'
def button(text,key='contacto',kind='primary'):return f'<a class="button {kind}" href="{link(key)}">{text} {icons["arrow"]}</a>'
def hero(kicker,title,copy,action=None):return '<section class="page-hero pad"><div><p class="eyebrow">'+kicker+'</p><h1>'+title+'</h1></div><div class="page-intro"><p>'+copy+'</p>'+(''+action if action else '')+'</div></section>'
def editorial_art(label='Streaming',word='DIRECTO'):return '<div class="editorial-art" aria-label="Gráfico editorial conceptual, no fotografía de trabajo"><span>'+label+'</span><strong>'+word+'</strong><span>Directo Producciones</span></div>'
def shell(body,key):
 h=header
 nav='<nav class="desktop-nav" aria-label="Principal">'+''.join('<a '+('class="active" aria-current="page" ' if k==key or (key=='articulo' and k=='blog') else '')+'href="'+link(k)+'">'+n+'</a>' for k,n in navpages[:-1])+'</nav>'
 h=re.sub(r'<nav class="desktop-nav".*?</nav>',nav,h,flags=re.S).replace('href="#inicio"','href="inicio.html?preview=1"').replace('href="#contacto"','href="contacto.html?preview=1"').replace('aria-controls="mobile-menu"','aria-controls="suite-menu"')
 f=footer
 replacements={'#inicio':'inicio','#streaming':'servicios','#colaboraciones':'clientes'}
 for a,b in replacements.items():f=f.replace('href="'+a+'"','href="'+link(b)+'"')
 for k,n in allpages:f=f.replace('<button data-destination="'+n+'">'+n+'</button>','<a href="'+link(k)+'">'+n+'</a>')
 menu='<nav class="suite-menu" id="suite-menu" aria-label="Principal móvil" hidden><div class="suite-menu-top"><strong>Directo Producciones</strong><button class="suite-menu-close" aria-label="Cerrar menú">'+icons['close']+'</button></div>'+''.join('<a href="'+link(k)+'">'+n+'</a>' for k,n in navpages)+'</nav>'
 return h+'<main>'+body+'</main>'+f+menu
service=hero('Servicios','Lo que necesitas<br>contar.','Streaming de eventos y realización televisiva. Comunicación y marketing digital para tu proyecto.','<a class="text-link" href="#servicios-streaming">Explora el streaming '+icons['right']+'</a>')
service+='<nav class="section-tabs pad" aria-label="Servicios en esta página"><a href="#servicios-streaming">Streaming</a><a href="#servicios-comunicacion">Comunicación</a><a href="#servicios-marketing">Marketing digital</a></nav>'
service+='<section id="servicios-streaming" class="service-feature pad"><div><p class="eyebrow">Streaming / El protagonista</p><h2>Del evento<br>a la pantalla.</h2><p>La retransmisión lleva lo que sucede en tu evento a una pantalla. La realización televisiva organiza cómo se presenta ese contenido.</p><div class="service-questions"><p>Eventos en streaming</p><p>TV online</p></div>'+button('Cuéntanos tu evento')+'</div>'+re.search(r'<div class="signal-stage signal-flow".*?</div></section>',home,re.S).group().replace('class="signal-stage signal-flow"','class="signal-stage signal-flow compact-flow"').removesuffix('</section>')+'</section>'
service+='<section id="tv-online" class="tv-format service-secondary section pad info-split"><div><p class="eyebrow">Streaming / TV online</p><h2>Un canal<br>para tu contenido.</h2></div><div><h3>TV online</h3><p>TV online y realización televisiva para emitir contenido online.</p><p>¿Qué quieres emitir? ¿Con qué programación? ¿En qué pantallas? Estas preguntas ayudan a definir tu canal.</p><a class="text-link" href="'+link('contacto')+'">Hablemos de tu TV online '+icons['arrow']+'</a></div></section>'
