service+='<section id="servicios-comunicacion" class="service-secondary section pad info-split"><div><p class="eyebrow">Comunicación</p><h2>Dar forma<br>al mensaje.</h2></div><div><h3>Comunicación corporativa</h3><p>Conversemos sobre el mensaje de tu organización y lo que necesitas comunicar.</p><div class="service-questions"><p>Comunicación corporativa</p><p>Gabinete de prensa</p></div><a class="text-link" href="'+link('contacto')+'">Hablemos de comunicación '+icons['arrow']+'</a></div></section>'
service+='<section id="servicios-marketing" class="service-secondary section pad info-split"><div><p class="eyebrow">Marketing digital</p><h2>La conversación<br>continúa.</h2></div><div><h3>Tu proyecto en digital</h3><p>Exploremos la presencia digital de tu proyecto y los canales que necesitas trabajar.</p><div class="service-questions"><p>Marketing digital</p><p>Redes sociales</p></div><a class="text-link" href="'+link('contacto')+'">Cuéntanos qué necesitas '+icons['arrow']+'</a></div></section>'+contact
clients=hero('Clientes','En buena<br>compañía.','Instituciones, empresas y marcas que forman parte de la trayectoria de Directo Producciones.')+'<section class="pad section client-logo-band" style="padding-top:32px"><div class="client-directory">'
for a in manifest:clients+='<figure class="directory-cell"><div class="directory-logo '+('logo-dark' if a['file'].endswith('hotel_motilla.svg') else '')+'"><img src="'+a['file']+'" alt="'+html.escape(a['name'])+'"></div><figcaption>'+html.escape(a['name'])+'</figcaption></figure>'
clients+='</div></section>'+metrics+testimonials+contact
about=hero('Quiénes somos','Directo<br>Producciones.','Una productora de streaming, comunicación y marketing digital.')
